commands.script:
const file = await app.pickFile({ title: '导入 Word 文档', extensions: ['docx', 'docm', 'doc'] });
if (!file) return;
const result = await app.importDocx(file.path);
const name = file.name.replace(/\.(docx|docm)$/i, '') + '.md';
await app.createDocument(result.markdown, name);
if (result.warnings && result.warnings.length) app.toast(result.warnings.join('；'));
